<script>
    /* ══════════════════════════════════════════
       SPECIALIZATION & SKILL PAGE NAVIGATION
    ══════════════════════════════════════════ */

    /* Map spc-card & skill-card clicks to their pages */
    const spcPageMap = {
        'salla':    'page-salla',
        'zid':      'page-zid',
        'shopify':  'page-shopify',
        'wordpress':'page-wordpress',
        'cwv':      'page-cwv',
        'schema':   'page-schema',
        'keyword':  'page-keyword',
        'aisearch': 'page-aisearch'
    };

    function showPage(pid){
        document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
        const pg=document.getElementById(pid);
        if(pg){
            pg.classList.add('active');
            window.scrollTo({top:0,behavior:'instant'});
            setTimeout(function(){
                if(window.lucide)lucide.createIcons();
                faq();
                // propagate current lang to spage
                document.documentElement.setAttribute('data-lang',lang);
            },60);
        }
    }

    /* Attach click handlers to spc cards */
    document.querySelectorAll('[data-spc]').forEach(function(card){
        card.style.cursor='pointer';
        card.addEventListener('click',function(){
            const key=this.getAttribute('data-spc');
            if(spcPageMap[key]) showPage(spcPageMap[key]);
        });
    });

    /* Attach click handlers to skill (tool) cards */
    document.querySelectorAll('[data-skill]').forEach(function(card){
        card.style.cursor='pointer';
        card.addEventListener('click',function(){
            const key=this.getAttribute('data-skill');
            if(spcPageMap[key]) showPage(spcPageMap[key]);
        });
    });

    /* Salla FAQ data injection */
    (function(){
        const faqsAr = [
            {q:'كم يستغرق ظهور نتائج سيو سلة؟', a:'في الغالب تبدأ التحسينات تظهر خلال 4-8 أسابيع للكلمات الأقل منافسة، و3-6 أشهر للكلمات التنافسية في السوق السعودي.'},
            {q:'هل تقدر تحسن كل منتجات متجري؟', a:'نعم، لدي تجربة واسعة في رفع Meta Tags وأوصاف المنتجات برمجياً عبر Salla MCP API لأي عدد من المنتجات.'},
            {q:'هل تعمل مع متاجر سلة الجديدة؟', a:'نعم، أساعد المتاجر الجديدة في البداية الصحيحة — إعداد GSC وSitemap وSchema والكلمات المفتاحية من اليوم الأول.'},
            {q:'ما الأدوات التي تستخدمها لتحليل سلة؟', a:'Ahrefs وSEMrush وScreaming Frog وGoogle Search Console وGoogle Analytics 4 وSalla MCP API.'},
            {q:'هل تحسين سيو سلة يزيد مبيعاتي؟', a:'نعم بشكل مباشر — كلمات مفتاحية تجارية أعلى تعني زيارات بنية شرائية أعلى تعني مبيعات أكثر.'}
        ];
        const faqsEn = [
            {q:'How long before Salla SEO results appear?', a:'Usually improvements start showing within 4-8 weeks for low-competition keywords, and 3-6 months for competitive keywords in the Saudi market.'},
            {q:'Can you optimize all my store products?', a:'Yes, I have extensive experience uploading Meta Tags and product descriptions programmatically via Salla MCP API for any number of products.'},
            {q:'Do you work with new Salla stores?', a:'Yes, I help new stores start correctly — GSC setup, Sitemap, Schema, and keyword research from day one.'},
            {q:'What tools do you use for Salla analysis?', a:'Ahrefs, SEMrush, Screaming Frog, Google Search Console, Google Analytics 4, and Salla MCP API.'},
            {q:'Does Salla SEO increase my sales?', a:'Yes, directly — higher commercial keywords ranking means higher purchase-intent traffic which means more sales.'}
        ];
        const container = document.getElementById('salla-faq');
        if(!container) return;
        const faqs = lang==='ar' ? faqsAr : faqsEn;
        container.innerHTML = faqs.map(f=>`
    <div class="faq-item">
      <div class="faq-q">${f.q}<i data-lucide="chevron-down"></i></div>
      <div class="faq-a">${f.a}</div>
    </div>`).join('');
    })();

    /* Fix existing showSP to also handle new pages */
    const _origShowSP = window.showSP;
    window.showSP = function(id){
        if(id && id.startsWith('page-')){
            showPage(id); return;
        }
        if(_origShowSP) _origShowSP(id);
        else {
            document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
            document.getElementById('page-service').classList.add('active');
            window.scrollTo({top:0,behavior:'instant'});
            setTimeout(function(){if(window.lucide)lucide.createIcons();},60);
        }
    };

    /* Propagate lang toggle to spage titles */
    const _origSetLang = window.setLang;
    window.setLang = function(l){
        if(_origSetLang) _origSetLang(l);
        // force re-show lang inside spage
        document.querySelectorAll('.spage-title.ar,.spage-title.en').forEach(function(el){
            if(el.classList.contains('ar')) el.style.display = l==='ar'?'block':'none';
            if(el.classList.contains('en')) el.style.display = l==='en'?'block':'none';
        });
        document.querySelectorAll('.spage-back svg').forEach(function(svg){
            svg.setAttribute('data-lucide', l==='ar'?'arrow-right':'arrow-left');
        });
        if(window.lucide) lucide.createIcons();
    };

    /* Add SEO meta per page (pushState) for crawlability signals */
    function updateMeta(title,desc){
        document.title = title;
        let m=document.querySelector('meta[name="description"]');
        if(m) m.content=desc;
    }

    document.querySelectorAll('#page-salla .spage-back').forEach(b=>b.addEventListener('click',function(){updateMeta('محمد يحيى — خبير SEO','خبير سيو متخصص');}));

    /* Init FAQ for all spage sections on load */
    document.addEventListener('DOMContentLoaded',function(){
        faq();
    });
</script>
